<?php require __DIR__.'/../../bootstrap/app.php';role_required('staff');$db=Database::get();$rows=$db->query("SELECT sr.id,u.name customer,s.name service,sr.status FROM service_requests sr JOIN users u ON u.id=sr.customer_id JOIN services s ON s.id=sr.service_id ORDER BY sr.id DESC LIMIT 40")->fetchAll();$title='Staff dashboard';require __DIR__.'/../../app/Views/header.php';?><section class="section"><div class="container"><h1>Staff dashboard</h1><p>Welcome, <?=e(user()['name'])?>.</p><div class="dash"><aside class="side"><h4>YEHA Staff</h4><?php foreach(['Overview'=>'dashboard.php','Service requests'=>'admin/requests.php','Quotations'=>'admin/quotations.php','Messages'=>'admin/messages.php','My profile'=>'profile.php','Home'=>'index.php'] as $n=>$p):?><a href="<?=e(url($p))?>"><?=e($n)?></a><?php endforeach;?><a href="<?=e(url('logout.php'))?>">Logout</a></aside><div><h2>Workspace</h2><table class="table"><tr><th>ID</th><th>Customer</th><th>Service</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['customer'])?></td><td><?=e($r['service'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div></div></div></section><?php require __DIR__.'/../../app/Views/footer.php';?>